from solution import has_close_elements

class TestHasCloseElements:
    """Test suite for has_close_elements function."""

    def test_no_close_elements(self):
        """Test case from docstring: no elements closer than threshold."""
        assert has_close_elements([1.0, 2.0, 3.0], 0.5) is False

    def test_has_close_elements(self):
        """Test case from docstring: elements 2.8 and 3.0 are within 0.3."""
        assert has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3) is True

    def test_single_element(self):
        """Single element list should never have close pairs."""
        assert has_close_elements([5.0], 0.1) is False

    def test_empty_list(self):
        """Empty list should return False."""
        assert has_close_elements([], 0.1) is False

    def test_exact_threshold(self):
        """Distance exactly equal to threshold should NOT be considered close."""
        assert has_close_elements([1.0, 2.0], 1.0) is False

    def test_just_under_threshold(self):
        """Distance just under threshold should return True."""
        assert has_close_elements([1.0, 1.99], 0.99) is True

    def test_negative_numbers__a0(self):
        """Should work correctly with negative numbers."""
        assert has_close_elements([-5.0, -4.9], 0.1) is True

    def test_negative_numbers__a1(self):
        """Should work correctly with negative numbers."""
        assert has_close_elements([-5.0, -4.9], 0.2) is False

    def test_mixed_positive_negative__a0(self):
        """Should work correctly with mixed positive and negative numbers."""
        assert has_close_elements([-1.0, 0.9], 0.1) is True

    def test_mixed_positive_negative__a1(self):
        """Should work correctly with mixed positive and negative numbers."""
        assert has_close_elements([-1.0, 0.9], 0.2) is False

    def test_float_precision__a0(self):
        """Test with floating point numbers that are very close."""
        assert has_close_elements([1.0000001, 1.0000002], 5e-08) is True

    def test_float_precision__a1(self):
        """Test with floating point numbers that are very close."""
        assert has_close_elements([1.0000001, 1.0000002], 1e-07) is False

    def test_identical_elements__a0(self):
        """Identical elements should always return True (distance 0)."""
        assert has_close_elements([5.0, 5.0], 0.1) is True

    def test_identical_elements__a1(self):
        """Identical elements should always return True (distance 0)."""
        assert has_close_elements([5.0, 5.0, 5.0], 0.1) is True

    def test_large_threshold(self):
        """With a very large threshold, any distinct elements should be close."""
        assert has_close_elements([1.0, 100.0], 1000.0) is True

    def test_small_threshold(self):
        """With a very small threshold, only nearly identical elements should be close."""
        assert has_close_elements([1.0, 1.0000001], 1e-08) is True

